1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
25	
26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
28	
29	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	const basePremiumPerItemOf = (itemType: string): number => {
39	  const basePremium = BASE_PREMIUM_BY_ITEM_TYPE[itemType];
40	  if (basePremium === undefined) {
41	    throw new Error(`Unknown item type: ${itemType}`);
42	  }
43	  return basePremium;
44	};
45	
46	// Percentages are always taken as `amount * percent / 100`, never `amount * 1.15`:
47	// exact fractional intermediates, a single rounding at the very end.
48	const percentOf = (amount: number, percent: number): number =>
49	  (amount * percent) / 100;
50	
51	const COMPONENT_BLOCK_SIZE = 3;
52	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
53	
54	const countByItemType = (items: Item[]): Map<string, number> =>
55	  items.reduce(
56	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
57	    new Map<string, number>(),
58	  );
59	
60	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
61	
62	const isComponent = (itemType: string): boolean =>
63	  COMPONENT_TYPES.has(itemType);
64	
65	const basePremiumForCountOf = (itemType: string, count: number): number =>
66	  isComponent(itemType) && count === COMPONENT_BLOCK_SIZE
67	    ? COMPONENT_BLOCK_BASE_PREMIUM
68	    : count * basePremiumPerItemOf(itemType);
69	
70	const sum = (amounts: number[]): number =>
71	  amounts.reduce((total, amount) => total + amount, 0);
72	
73	const policyBasePremiumOf = (items: Item[]): number =>
74	  sum(
75	    [...countByItemType(items)].map(([itemType, count]) =>
76	      basePremiumForCountOf(itemType, count),
77	    ),
78	  );
79	
80	const CURSE_SURCHARGE_PERCENT = 50;
81	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
82	const HIGH_ENCHANTMENT_LEVEL = 5;
83	
84	const isHighlyEnchanted = (item: Item): boolean =>
85	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
86	
87	const itemSurchargePercentOf = (item: Item): number =>
88	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
89	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
90	
91	// Item-level modifiers apply to the affected ITEM's own base premium.
92	const itemSurchargesOf = (items: Item[]): number =>
93	  sum(
94	    items.map((item) =>
95	      percentOf(basePremiumPerItemOf(item.type), itemSurchargePercentOf(item)),
96	    ),
97	  );
98	
99	const LOYALTY_DISCOUNT_PERCENT = 20;
100	const LOYALTY_YEARS = 2;
101	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
102	
103	const isLongStanding = (customer: Customer): boolean =>
104	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
105	
106	// Policy-wide modifiers are signed percentages OF THE POLICY BASE PREMIUM (the sum
107	// of item base premiums) — never of the running total, so item surcharges stay
108	// outside their scope. Positive is a surcharge, negative a discount. Adding a
109	// policy-wide modifier means adding one entry here.
110	const policyModifierPercentsOf = (
111	  customer: Customer,
112	  isFollowUpContract: boolean,
113	): number[] => [
114	  FIRST_INSURANCE_SURCHARGE_PERCENT,
115	  ...(isLongStanding(customer) ? [-LOYALTY_DISCOUNT_PERCENT] : []),
116	  ...(isFollowUpContract ? [-FOLLOW_UP_DISCOUNT_PERCENT] : []),
117	];
118	
119	const quotePremium = (
120	  items: Item[],
121	  customer: Customer,
122	  isFollowUpContract: boolean,
123	): number => {
124	  const policyBasePremium = policyBasePremiumOf(items);
125	  const policyModifiers = sum(
126	    policyModifierPercentsOf(customer, isFollowUpContract).map((percent) =>
127	      percentOf(policyBasePremium, percent),
128	    ),
129	  );
130	
131	  // The processing fee is added last, after every modifier.
132	  return Math.ceil(
133	    policyBasePremium +
134	      itemSurchargesOf(items) +
135	      policyModifiers +
136	      PROCESSING_FEE,
137	  );
138	};
139	
140	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
141	  sword: 1000,
142	  amulet: 600,
143	  staff: 800,
144	  potion: 400,
145	  rune: 250,
146	  moonstone: 250,
147	};
148	
149	const DEDUCTIBLE_PER_DAMAGE = 100;
150	const CAP_MULTIPLIER = 2;
151	
152	const insuranceSumOf = (items: Item[]): number =>
153	  sum(items.map((item) => INSURANCE_VALUE_BY_ITEM_TYPE[item.type]));
154	
155	// The claim-side enchantment threshold (8) is deliberately distinct from the
156	// premium-side one (HIGH_ENCHANTMENT_LEVEL, 5) — different rules, different numbers.
157	const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
158	const REDUCED_REIMBURSEMENT_PERCENT = 50;
159	
160	const reimbursementFor = (damage: Damage, item: Item): number =>
161	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT
162	    ? percentOf(damage.amount, REDUCED_REIMBURSEMENT_PERCENT)
163	    : damage.amount;
164	
165	const payoutForDamage = (damage: Damage, item: Item): number =>
166	  reimbursementFor(damage, item) - DEDUCTIBLE_PER_DAMAGE;
167	
168	// A policy is what a quote step leaves behind for later claim steps to draw on:
169	// the insured items and the cap those items entitle the holder to. `remainingCap`
170	// is the only thing a claim consumes, so it is the one mutable field.
171	type Policy = {
172	  insuredItems: Item[];
173	  remainingCap: number;
174	};
175	
176	const issuePolicy = (insuredItems: Item[]): Policy => ({
177	  insuredItems,
178	  remainingCap: CAP_MULTIPLIER * insuranceSumOf(insuredItems),
179	});
180	
181	// Each damage entry is a separate damaged item, so entries consume the insured
182	// items one for one: two sword damages need two insured swords.
183	const damagedItemsOf = (policy: Policy, damages: Damage[]): Item[] => {
184	  const unclaimedItems = [...policy.insuredItems];
185	
186	  return damages.map((damage) => {
187	    if (damage.amount < 0) {
188	      throw new Error(
189	        `Damage amount must not be negative: ${damage.amount} for ${damage.itemType}`,
190	      );
191	    }
192	
193	    const index = unclaimedItems.findIndex(
194	      (item) => item.type === damage.itemType,
195	    );
196	    if (index === -1) {
197	      throw new Error(
198	        `Damage entry not covered by the policy: ${damage.itemType}`,
199	      );
200	    }
201	
202	    return unclaimedItems.splice(index, 1)[0];
203	  });
204	};
205	
206	const settleClaim = (policy: Policy, damages: Damage[]): StepResult => {
207	  const damagedItems = damagedItemsOf(policy, damages);
208	  const desiredPayout = Math.floor(
209	    sum(
210	      damages.map((damage, index) =>
211	        payoutForDamage(damage, damagedItems[index]),
212	      ),
213	    ),
214	  );
215	
216	  // The cap is a per-policy budget: what a claim pays out, it consumes.
217	  const payout = Math.min(desiredPayout, policy.remainingCap);
218	  policy.remainingCap -= payout;
219	
220	  return { payout, remainingCap: policy.remainingCap };
221	};
222	
223	export const runScenario = (scenario: Scenario): StepResult[] => {
224	  // A claim's `policy` is the index of the QUOTE STEP that issued it, so policies
225	  // are keyed by step index rather than by order of issue — the two differ as soon
226	  // as quotes and claims interleave.
227	  const policiesByStep = new Map<number, Policy>();
228	
229	  return scenario.steps.map((step, stepIndex) => {
230	    if (step.op === "claim") {
231	      return settleClaim(policiesByStep.get(step.policy)!, step.incident.damages);
232	    }
233	
234	    const premium = quotePremium(
235	      step.items,
236	      scenario.customer,
237	      policiesByStep.size > 0,
238	    );
239	    policiesByStep.set(stepIndex, issuePolicy(step.items));
240	
241	    return { premium };
242	  });
243	};
